import { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import trainRegistryData from "@/data/trainRegistry.json";
import LiveTrainClient from "./LiveTrainClient";

const trainRegistry = trainRegistryData as Record<string, string>;

const OG_IMAGE_URL = "https://www.trayago.in/branding/og-image.png";

interface TrainRouteIdentity {
  trainNo: string;
  isValid: boolean;
  isKnown: boolean;
  trainName: string | null;
}

/**
 * Validates and normalizes Indian Railways train numbers against trainRegistry.json.
 * - Rejects malformed / non-numeric slugs (404).
 * - Handles leading-zero & 3–5 digit registry keys (e.g., "01234" -> "1234").
 * - Allows unknown 5-digit numbers (e.g., new special trains) with HTTP 200 + noindex.
 */
function resolveTrainRouteIdentity(rawTrainNo: string): TrainRouteIdentity {
  const trainNo = (rawTrainNo || "").trim();
  if (!/^\d{3,5}$/.test(trainNo)) {
    return { trainNo, isValid: false, isKnown: false, trainName: null };
  }

  const stripped = trainNo.replace(/^0+/, "");
  const matchedName =
    trainRegistry[trainNo] ??
    (stripped && stripped !== trainNo ? trainRegistry[stripped] : undefined) ??
    null;

  if (matchedName) {
    return { trainNo, isValid: true, isKnown: true, trainName: matchedName };
  }

  // Genuine 5-digit unknown trains (e.g., temporary special trains) stay reachable (HTTP 200, noindex)
  if (/^\d{5}$/.test(trainNo)) {
    return { trainNo, isValid: true, isKnown: false, trainName: null };
  }

  // 3–4 digit numbers absent from trainRegistry.json are invalid slugs -> 404
  return { trainNo, isValid: false, isKnown: false, trainName: null };
}

// 1. Dynamic SEO Metadata for Train Schedule / Live Status Page
export async function generateMetadata({ params }: { params: Promise<{ trainNo: string }> }): Promise<Metadata> {
  const resolvedParams = await params;
  const identity = resolveTrainRouteIdentity(resolvedParams.trainNo);

  if (!identity.isValid) {
    return {
      title: "Train Not Found | Trayago",
      robots: {
        index: false,
        follow: false,
      },
    };
  }

  const trainNo = identity.trainNo;
  const canonical = `https://www.trayago.in/live/${trainNo}`;
  const label = identity.trainName ? `${trainNo} ${identity.trainName}` : `Train ${trainNo}`;

  const title = `${label} — Schedule, Time Table & Live Running Status | Trayago`;
  const description = `${label} schedule and time table on Trayago: station-wise arrival and departure times, intermediate stops, route, and current running status with delay information.`;

  return {
    title,
    description,
    keywords: `train ${trainNo} schedule, train ${trainNo} time table, train ${trainNo} route, train ${trainNo} running status, train timetable, train timings, train arrival time, train departure time`,
    alternates: {
      canonical,
    },
    robots: {
      index: identity.isKnown,
      follow: true,
    },
    openGraph: {
      type: "website",
      title,
      description,
      url: canonical,
      siteName: "Trayago",
      images: [
        {
          url: OG_IMAGE_URL,
          width: 1200,
          height: 630,
          alt: `${label} Live Running Status — Trayago`,
        },
      ],
    },
    twitter: {
      card: "summary_large_image",
      title: `${label} — Schedule & Live Running Status`,
      description,
      images: [OG_IMAGE_URL],
    },
  };
}

interface PageProps {
  params: Promise<{ trainNo: string }>;
}

export default async function LiveTrainDetailPage({ params }: PageProps) {
  const resolvedParams = await params;
  const identity = resolveTrainRouteIdentity(resolvedParams.trainNo);

  if (!identity.isValid) {
    notFound();
  }

  const trainNo = identity.trainNo;
  const canonical = `https://www.trayago.in/live/${trainNo}`;

  // 2. Structured Data Schemas
  const breadcrumbSchema = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      {
        "@type": "ListItem",
        position: 1,
        name: "Home",
        item: "https://www.trayago.in",
      },
      {
        "@type": "ListItem",
        position: 2,
        name: "Live Train Status",
        item: "https://www.trayago.in/live",
      },
      {
        "@type": "ListItem",
        position: 3,
        name: `Train ${trainNo} Schedule & Live Status`,
        item: canonical,
      },
    ],
  };

  const webPageSchema = {
    "@context": "https://schema.org",
    "@type": "WebPage",
    name: `Train ${trainNo} — Schedule, Time Table & Live Running Status`,
    description: `Station-wise schedule, arrival and departure times, route, and current running status for train ${trainNo} on Indian Railways.`,
    url: canonical,
    inLanguage: "en-IN",
    isPartOf: {
      "@type": "WebSite",
      name: "Trayago",
      url: "https://www.trayago.in",
    },
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbSchema) }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(webPageSchema) }}
      />
      <LiveTrainClient initialTrainName={identity.trainName ?? undefined} />

      {/* Explanatory schedule content — rendered below the live timeline so the tool stays primary */}
      <section
        aria-labelledby={`train-schedule-guide-${trainNo}`}
        className="w-full px-4 md:px-8 pb-16"
      >
        <div className="max-w-4xl mx-auto w-full border-t border-strong pt-12 space-y-10 text-sm text-secondary leading-relaxed">
          <div className="space-y-3">
            <h2
              id={`train-schedule-guide-${trainNo}`}
              className="text-xl font-black text-main"
            >
              Train {trainNo} — schedule and time table
            </h2>
            <p>
              The timeline above shows the <strong>train schedule</strong> for
              train {trainNo}: every station on its route, the scheduled{" "}
              <strong>arrival time</strong> and{" "}
              <strong>departure time</strong> at each stop, and how the train is
              currently running against that timetable. Stations already passed,
              the current position, and upcoming stops are marked separately.
            </p>
          </div>

          <div className="space-y-3">
            <h3 className="text-base font-bold text-main">
              What is a train schedule?
            </h3>
            <p>
              A railway <strong>train timetable</strong> is the published plan
              for a service. It lists the train number and name, the sequence of{" "}
              <strong>intermediate stations</strong> between origin and
              destination, and the time the train is scheduled to reach and
              leave each one. Because the same numbered train runs to the same
              timetable on its operating days, the schedule is what lets you
              work out boarding time, journey duration, and whether a particular
              station is even a stop.
            </p>
          </div>

          <div className="space-y-3">
            <h3 className="text-base font-bold text-main">
              Understanding arrival and departure times
            </h3>
            <p>
              <strong>Arrival time</strong> is when the train is scheduled to
              reach a station; <strong>departure time</strong> is when it is
              scheduled to leave. The gap between them is the halt, which can be
              a couple of minutes at a small station or much longer at a major
              junction. At the originating station only a departure time
              applies, and at the final destination only an arrival time does.
            </p>
            <p>
              Board against the departure time, but reach the platform well
              before it — a short halt leaves little margin. Where a journey
              runs past midnight, the day counter distinguishes a departure late
              on day one from an arrival early on day two.
            </p>
          </div>

          <div className="space-y-3">
            <h3 className="text-base font-bold text-main">
              Scheduled timings versus current running
            </h3>
            <p>
              A timetable describes the plan; it is not a promise about today.
              Trains can run late, and delay can grow or shrink over the course
              of a route. This page pairs the two: the scheduled timings from
              the <strong>train route schedule</strong> alongside the latest
              reported running information, so you can see both what should
              happen and what is actually happening.
            </p>
            <p>
              Timetables themselves are also revised periodically by Indian
              Railways, and individual runs can be cancelled or diverted. For
              platform numbers and last-minute changes, confirm with official
              station announcements.
            </p>
          </div>

          <div className="space-y-3">
            <h3 className="text-base font-bold text-main">
              Why the time table matters
            </h3>
            <p>
              A schedule answers the practical questions: which stop to board
              at, how long the journey takes, whether there is enough halt time
              to step off, when someone should leave home to collect you, and
              whether a connecting train is realistic once the current delay is
              taken into account.
            </p>
          </div>

          <div className="space-y-3 border-t border-strong pt-8">
            <h3 className="text-base font-bold text-main">Related tools</h3>
            <p>
              Check a booking with{" "}
              <Link
                href="/pnr"
                className="text-primary font-semibold hover:underline"
              >
                PNR status and confirmation prediction
              </Link>
              , look up another train on{" "}
              <Link
                href="/live"
                className="text-primary font-semibold hover:underline"
              >
                live train running status
              </Link>
              , plan a route with the{" "}
              <Link
                href="/"
                className="text-primary font-semibold hover:underline"
              >
                Trayago train search
              </Link>
              , or track journeys on the{" "}
              <Link
                href="/app"
                className="text-primary font-semibold hover:underline"
              >
                Trayago Android app
              </Link>
              .
            </p>
            <p className="text-xs text-muted">
              Trayago is an independent travel intelligence platform and is not
              affiliated with, endorsed by, or operated by IRCTC or Indian
              Railways. Ticket booking is completed through official booking
              platforms.
            </p>
          </div>
        </div>
      </section>
    </>
  );
}
